-- Researched leads, loaded as PENDING SUGGESTIONS (not live listings).
-- Generated by scripts/build-candidate-seed.mjs. Safe to run more than once.
-- Run in the Supabase SQL editor after the migrations. Then open the app's Review queue,
-- check each lead with its operator, and use "Add as a listing to review".
-- Coordinates are suburb centres; fix the pin when you edit the listing.

insert into public.suggestions (user_id, name, venue_type, state, locality, postcode, lat, lng, products, notes)
select null, 'Carriageworks Farmers Market', 'farmers_market', 'NSW', 'Eveleigh', '2015', -33.91, 151.195, '{}', 'UNVERIFIED lead from public listings (checked 13 Nov 2026). Saturdays 8am-1pm (several listings agree), undercover. Address in listings: 245 Wilson St, Eveleigh (Sydney.com.au gives the entrance as 243 Wilson St, Darlington). Free entry. Sources: https://www.sydney.com.au/carriageworks-farmers-market.htm and https://qantas.com/travelinsider/en/explore/australia/new-south-wales/sydney/eveleigh-markets.html. Confirm with the operator before publishing.'
where not exists (select 1 from public.suggestions where name = 'Carriageworks Farmers Market' and postcode = '2015');

